import assert from 'node:assert/strict';
import { Scene } from 'three';
import { Terrain, CORE_EXTENT } from './src/world/Terrain.js';
import { Level } from './src/world/Level.js';
import { Player } from './src/gameplay/Player.js';
import { PhysicsWorld } from './src/gameplay/Physics.js';
import { Input } from './src/core/Input.js';
import { Menus } from './src/ui/Menus.js';
globalThis.window = new EventTarget(); globalThis.document = new EventTarget();
const ctx = { scene: new Scene(), engine: { frame: 0 }, playerCamera: { yaw: 0 }, quality: { tier: 1, terrainSegments: 160 } };
ctx.physics = new PhysicsWorld(ctx); await ctx.physics.init();
ctx.terrain = new Terrain(ctx); const t = ctx.terrain;
t.gridN = 161; t.cell = CORE_EXTENT / 160; t.height = new Float32Array(t.gridN ** 2); t.flow = new Float32Array(t.gridN ** 2); t.macroHeight = new Float32Array(t.macroN ** 2);
for (const method of ['_buildMacroField','_buildCoreField','_buildSplines','_carveFeatures','_erode','_finishCarve','_blendEdges']) await t[method](0, 1);
t._registerPhysics();
ctx.level = new Level(ctx); ctx.level._probeGround();
for (let i = 0; i < 4; i++) for (let half = 0; half < 2; half++) ctx.level._buildStairFlight(i, half);
ctx.level._buildTorii(0); ctx.level._buildBoundary(); ctx.level._realizePhysics(); ctx.level._buildSpawnPoints();
ctx.input = new Input(new EventTarget()); ctx.player = new Player(ctx); ctx.player._createRig = async () => {}; await ctx.player.init();
const start = ctx.player.position.toArray(); const expected = ctx.level.playerSpawn.position;
assert.equal(ctx.player.position.distanceTo(expected), 0);
const event = new Event('keydown', { cancelable: true }); Object.defineProperty(event, 'code', { value: 'KeyW' }); window.dispatchEvent(event);
for (let frame = 0; frame < 120; frame++) { ctx.engine.frame++; ctx.input.update(); ctx.player.update(1/60, ctx.engine.frame/60, 1/60); ctx.input.endFrame(); }
const end = ctx.player.position.toArray(); assert.ok(start[2] - end[2] > 5); assert.ok(end.every(Number.isFinite));
Menus.prototype.restart.call({ ctx, skipIntro(){}, _setPaused(value){assert.equal(value,false);} });
assert.equal(ctx.player.position.distanceTo(expected),0); assert.equal(ctx.player.controller.position.distanceTo(expected),0);
console.log(JSON.stringify({start,end,forwardMetres:start[2]-end[2],restart:ctx.player.position.toArray()})); ctx.input.dispose();
